import{_ as n,a0 as d,w as o,s as r,ao as p,I as s,a1 as l,A as t,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"邏輯卷管理（LVM） Linux 用户指南 | LCTT x X-CMD","titleTemplate":false,"description":"邏輯卷管理（LVM） Linux 用户指南 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"邏輯卷管理（LVM） Linux 用户指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"邏輯卷管理（LVM） Linux 用户指南 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20160922 A Linux users guide to Logical Volume Management","title":"邏輯卷管理（LVM） Linux 用户指南","tag":"201712","desc":""},"relativePath":"201712/20160922 A Linux users guide to Logical Volume Management.md","filePath":"[post].md"}'),h={name:"201712/20160922 A Linux users guide to Logical Volume Management.md"};function c(u,e,g,b,k,f){const i=d("Link");return o(),r("div",null,[e[14]||(e[14]=p('<h1 id="邏輯卷管理-lvm-linux-用户指南" tabindex="-1">邏輯卷管理（LVM） Linux 用户指南 <a class="header-anchor" href="#邏輯卷管理-lvm-linux-用户指南" aria-label="Permalink to “邏輯卷管理（LVM） Linux 用户指南”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_other11x_cc.png?itok=I_kCDYj0" alt="Logical Volume Management (LVM)" title="Logical Volume Management (LVM)"></p><p>Image by : opensource.com</p><p>管理磁盤空間對系統管理員來説是一件重要的日常工作。一旦磁盤空間耗盡就需要進行一系列耗時而又複雜的任務，以提升磁盤分區中可用的磁盤空間。它也需要系統離線才能處理。通常這種任務會涉及到安裝一個新的硬盤、引導至恢復模式或者單用户模式、在新硬盤上創建一個分區和一個文件系統、掛載到臨時掛載點去從一個太小的文件系統中移動數據到較大的新位置、修改 <code>/etc/fstab</code> 文件的內容來反映出新分區的正確設備名、以及重新引導來重新掛載新的文件系統到正確的掛載點。</p><p>我想告訴你的是，當 LVM （邏輯卷管理）首次出現在 Fedora Linux 中時，我是非常抗拒它的。我最初的反應是，我並不需要在我和我的設備之間有這種額外的抽象層。結果是我錯了，邏輯卷管理是非常有用的。</p><p>LVM 讓磁盤空間管理非常靈活。它提供的功能諸如在文件系統已掛載和活動時，很可靠地增加磁盤空間到一個邏輯卷和它的文件系統中，並且，它也允許你將多個物理磁盤和分區融合進一個可以分割成邏輯卷（LV）的單個卷組（VG）中。</p><p>卷管理也允許你去減少分配給一個邏輯卷的磁盤空間數量，但是，這裏有兩個要求，第一，卷必須是未掛載的。第二，在卷空間調整之前，文件系統本身的空間大小必須先被減少。</p><p>有一個重要的提示是，文件系統本身必須允許重新調整大小的操作。當重新提升文件系統大小的時候，EXT2、3 和 4 文件系統都允許離線（未掛載狀態）或者在線（掛載狀態）重新調整大小。你應該去認真瞭解你打算去調整的文件系統的詳細情況，去驗證它們是否可以完全調整大小，尤其是否可以在線調整大小。</p><h3 id="即時擴展一個文件系統" tabindex="-1">即時擴展一個文件系統 <a class="header-anchor" href="#即時擴展一個文件系統" aria-label="Permalink to “即時擴展一個文件系統”">​</a></h3><p>在我安裝一個新的發行版到我的生產用機器中之前，我總是喜歡在一個 VirtualBox 虛擬機中運行這個新的發行版一段時間，以確保它沒有任何的致命的問題存在。在幾年前的一個早晨，我在我的主要使用的工作站上的虛擬機中安裝了一個新發行的 Fedora 版本。我認為我有足夠的磁盤空間分配給安裝虛擬機的主文件系統。但是，我錯了，大約在安裝到三分之一時，我耗盡了我的文件系統的空間。幸運的是，VirtualBox 檢測到了磁盤空間不足的狀態，並且暫停了虛擬機，然後顯示了一個明確指出問題所在的錯誤信息。</p><p>請注意，這個問題並不是虛擬機磁盤太小造成的，而是由於宿主機上空間不足，導致虛擬機上的虛擬磁盤在宿主機上的邏輯卷中沒有足夠的空間去擴展。</p><p>因為許多現在的發行版都缺省使用了邏輯卷管理，並且在我的卷組中有一些可用的空餘空間，我可以分配額外的磁盤空間到適當的邏輯卷，然後即時擴展宿主機的文件系統。這意味着我不需要去重新格式化整個硬盤，以及重新安裝操作系統或者甚至是重啓機器。我不過是分配了一些可用空間到適當的邏輯卷中，並且重新調整了文件系統的大小 —— 所有的這些操作都在文件系統在線並且運行着程序的狀態下進行的，虛擬機也一直使用着宿主機文件系統。在調整完邏輯卷和文件系統的大小之後，我恢復了虛擬機的運行，並且繼續進行安裝過程，就像什麼問題都沒有發生過一樣。</p><p>雖然這種問題你可能從來也沒有遇到過，但是，許多人都遇到過重要程序在運行過程中發生磁盤空間不足的問題。而且，雖然許多程序，尤其是 Windows 程序，並不像 VirtualBox 一樣寫的很好，且富有彈性，Linux 邏輯卷管理可以使它在不丟失數據的情況下去恢復，也不需要去進行耗時的安裝過程。</p><h3 id="lvm-結構" tabindex="-1">LVM 結構 <a class="header-anchor" href="#lvm-結構" aria-label="Permalink to “LVM 結構”">​</a></h3><p>邏輯卷管理的磁盤環境結構如下面的圖 1 所示。邏輯卷管理允許多個單獨的硬盤和/或磁盤分區組合成一個單個的卷組（VG）。卷組然後可以再劃分為邏輯卷（LV）或者被用於分配成一個大的單一的卷。普通的文件系統，如 EXT3 或者 EXT4，可以創建在一個邏輯捲上。</p><p>在圖 1 中，兩個完整的物理硬盤和一個第三塊硬盤的一個分區組合成一個單個的卷組。在這個卷組中創建了兩個邏輯卷和文件系統，比如，可以在每個邏輯捲上創建一個 EXT3 或者 EXT4 的文件系統。</p><p><img src="https://opensource.com/sites/default/files/resize/images/life-uploads/lvm-520x222.png" alt="lvm.png"></p><p><em>圖 1: LVM 允許組合分區和整個硬盤到卷組中</em></p><p>在一個主機上增加磁盤空間是非常簡單的，在我的經歷中，這種事情是很少的。下面列出了基本的步驟。你也可以創建一個完整的新卷組或者增加新的空間到一個已存在的邏輯卷中，或者創建一個新的邏輯卷。</p><h3 id="增加一個新的邏輯卷" tabindex="-1">增加一個新的邏輯卷 <a class="header-anchor" href="#增加一個新的邏輯卷" aria-label="Permalink to “增加一個新的邏輯卷”">​</a></h3><p>有時候需要在主機上增加一個新的邏輯卷。例如，在被提示包含我的 VirtualBox 虛擬機的虛擬磁盤的 <code>/home</code> 文件系統被填滿時，我決定去創建一個新的邏輯卷，以存儲包含虛擬磁盤在內的虛擬機數據。這將在我的 <code>/home</code> 文件系統中釋放大量的空間，並且也允許我去獨立地管理虛擬機的磁盤空間。</p><p>增加一個新的邏輯卷的基本步驟如下：</p><ol><li>如有需要，安裝一個新硬盤。</li><li>可選： 在硬盤上創建一個分區。</li><li>在硬盤上創建一個完整的物理卷（PV）或者一個分區。</li><li>分配新的物理捲到一個已存在的卷組（VG）中，或者創建一個新的卷組。</li><li>從卷空間中創建一個新的邏輯卷（LV）。</li><li>在新的邏輯卷中創建一個文件系統。</li><li>在 <code>/etc/fstab</code> 中增加適當的條目以掛載文件系統。</li><li>掛載文件系統。</li></ol><p>為了更詳細的介紹，接下來將使用一個示例作為一個實驗去教授關於 Linux 文件系統的知識。</p><h4 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h4><p>這個示例展示了怎麼用命令列去擴展一個已存在的卷組，並給它增加更多的空間，在那個空間上創建一個新的邏輯卷，然後在邏輯捲上創建一個文件系統。這個過程一直在運行着和已掛載的文件系統上執行。</p><p>警告：僅 EXT3 和 EXT4 文件系統可以在運行和掛載狀態下調整大小。許多其它的文件系統，包括 BTRFS 和 ZFS 是不能這樣做的。</p><h5 id="安裝硬盤" tabindex="-1">安裝硬盤 <a class="header-anchor" href="#安裝硬盤" aria-label="Permalink to “安裝硬盤”">​</a></h5><p>如果在系統中現有硬盤上的卷組中沒有足夠的空間可以增加，那麼可能需要去增加一塊新的硬盤，然後創建空間增加到邏輯卷中。首先，安裝物理硬盤，然後，接着執行後面的步驟。</p><h5 id="從硬盤上創建物理卷" tabindex="-1">從硬盤上創建物理卷 <a class="header-anchor" href="#從硬盤上創建物理卷" aria-label="Permalink to “從硬盤上創建物理卷”">​</a></h5><p>首先需要去創建一個新的物理卷（PV）。使用下面的命令，它假設新硬盤已經分配為 <code>/dev/hdd</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pvcreate /dev/hdd</span></span></code></pre></div><p>在新硬盤上創建一個任意分區並不是必需的。創建的物理卷將被邏輯卷管理器識別為一個新安裝的未處理的磁盤或者一個類型為 83 的 Linux 分區。如果你想去使用整個硬盤，創建一個分區並沒有什麼特別的好處，而且元數據所用的磁盤空間也能用做 PV 的一部分使用。</p><h5 id="擴展已存在的卷組" tabindex="-1">擴展已存在的卷組 <a class="header-anchor" href="#擴展已存在的卷組" aria-label="Permalink to “擴展已存在的卷組”">​</a></h5><p>在這個示例中，我將擴展一個已存在的卷組，而不是創建一個新的；你可以選擇其它的方式。在物理磁盤已經創建之後，擴展已存在的卷組（VG）去包含新 PV 的空間。在這個示例中，已存在的卷組命名為：MyVG01。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vgextend /dev/MyVG01 /dev/hdd</span></span></code></pre></div><h5 id="創建一個邏輯卷" tabindex="-1">創建一個邏輯卷 <a class="header-anchor" href="#創建一個邏輯卷" aria-label="Permalink to “創建一個邏輯卷”">​</a></h5><p>首先，在卷組中從已存在的空餘空間中創建邏輯卷。下面的命令創建了一個 50 GB 大小的 LV。這個卷組的名字為 MyVG01，然後，邏輯卷的名字為 Stuff。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lvcreate -L +50G --name Stuff MyVG01</span></span></code></pre></div><h5 id="創建文件系統" tabindex="-1">創建文件系統 <a class="header-anchor" href="#創建文件系統" aria-label="Permalink to “創建文件系統”">​</a></h5><p>創建邏輯卷並不會創建文件系統。這個任務必須被單獨執行。下面的命令在新創建的邏輯卷中創建了一個 EXT4 文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs -t ext4 /dev/MyVG01/Stuff</span></span></code></pre></div><h5 id="增加一個文件系統卷標" tabindex="-1">增加一個文件系統卷標 <a class="header-anchor" href="#增加一個文件系統卷標" aria-label="Permalink to “增加一個文件系統卷標”">​</a></h5><p>增加一個文件系統卷標，更易於在文件系統以後出現問題時識別它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>e2label /dev/MyVG01/Stuff Stuff</span></span></code></pre></div><h5 id="掛載文件系統" tabindex="-1">掛載文件系統 <a class="header-anchor" href="#掛載文件系統" aria-label="Permalink to “掛載文件系統”">​</a></h5><p>在這個時候，你可以創建一個掛載點，並在 <code>/etc/fstab</code> 文件系統中添加合適的條目，以掛載文件系統。</p><p>你也可以去檢查並校驗創建的卷是否正確。你可以使用 <code>df</code>、<code>lvs</code> 和 <code>vgs</code> 命令去做這些工作。</p><h3 id="在-lvm-文件系統中調整邏輯卷大小" tabindex="-1">在 LVM 文件系統中調整邏輯卷大小 <a class="header-anchor" href="#在-lvm-文件系統中調整邏輯卷大小" aria-label="Permalink to “在 LVM 文件系統中調整邏輯卷大小”">​</a></h3><p>從 Unix 的第一個版本開始，對文件系統的擴展需求就一直伴隨，Linux 也不例外。隨着有了邏輯卷管理（LVM），現在更加容易了。</p><ol><li>如有需要，安裝一個新硬盤。</li><li>可選： 在硬盤上創建一個分區。</li><li>在硬盤上創建一個完整的物理卷（PV）或者一個分區。</li><li>分配新的物理捲到一個已存在的卷組（VG）中，或者創建一個新的卷組。</li><li>從卷空間中創建一個新的邏輯卷（LV），或者用卷組中部分或全部空間擴展已有的邏輯卷。</li><li>如果創建了新的邏輯卷，那麼在上面創建一個文件系統。如果對已有的邏輯卷增加空間，使用 <code>resize2fs</code> 命令來增大文件系統來填滿邏輯卷。</li><li>在 <code>/etc/fstab</code> 中增加適當的條目以掛載文件系統。</li><li>掛載文件系統。</li></ol><h4 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to “示例”">​</a></h4><p>這個示例展示了怎麼用命令列去擴展一個已存在的卷組。它會給 <code>/Staff</code> 文件系統增加大約 50GB 的空間。這將生成一個可用於掛載的文件系統，在 Linux 2.6 內核（及更高）上可即時使用 EXT3 和 EXT4 文件系統。我不推薦你用於任何關鍵系統，但是這是可行的，我已經成功了好多次；即使是在根（<code>/</code>）文件系統上。是否使用自己把握風險。</p><p>警告：僅 EXT3 和 EXT4 文件系統可以在運行和掛載狀態下調整大小。許多其它的文件系統，包括 BTRFS 和 ZFS 是不能這樣做的。</p><h5 id="安裝硬盤-1" tabindex="-1">安裝硬盤 <a class="header-anchor" href="#安裝硬盤-1" aria-label="Permalink to “安裝硬盤”">​</a></h5><p>如果在系統中現有硬盤上的卷組中沒有足夠的空間可以增加，那麼可能需要去增加一塊新的硬盤，然後創建空間增加到邏輯卷中。首先，安裝物理硬盤，然後，接着執行後面的步驟。</p><h5 id="從硬盤上創建物理卷-1" tabindex="-1">從硬盤上創建物理卷 <a class="header-anchor" href="#從硬盤上創建物理卷-1" aria-label="Permalink to “從硬盤上創建物理卷”">​</a></h5><p>首先需要去創建一個新的物理卷（PV）。使用下面的命令，它假設新硬盤已經分配為 <code>/dev/hdd</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pvcreate /dev/hdd</span></span></code></pre></div><p>在新硬盤上創建一個任意分區並不是必需的。創建的物理卷將被邏輯卷管理器識別為一個新安裝的未處理的磁盤或者一個類型為 83 的 Linux 分區。如果你想去使用整個硬盤，創建一個分區並沒有什麼特別的好處，而且元數據所用的磁盤空間也能用做 PV 的一部分使用。</p><h5 id="增加物理捲到已存在的卷組" tabindex="-1">增加物理捲到已存在的卷組 <a class="header-anchor" href="#增加物理捲到已存在的卷組" aria-label="Permalink to “增加物理捲到已存在的卷組”">​</a></h5><p>在這個示例中，我將使用一個新的物理捲來擴展一個已存在的卷組。在物理卷已經創建之後，擴展已存在的卷組（VG）去包含新 PV 的空間。在這個示例中，已存在的卷組命名為：MyVG01。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vgextend /dev/MyVG01 /dev/hdd</span></span></code></pre></div><h5 id="擴展邏輯卷" tabindex="-1">擴展邏輯卷 <a class="header-anchor" href="#擴展邏輯卷" aria-label="Permalink to “擴展邏輯卷”">​</a></h5><p>首先，在卷組中從已存在的空餘空間中創建邏輯卷。下面的命令創建了一個 50 GB 大小的 LV。這個卷組的名字為 MyVG01，然後，邏輯卷的名字為 Stuff。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lvcreate -L +50G --name Stuff MyVG01</span></span></code></pre></div><h5 id="擴展文件系統" tabindex="-1">擴展文件系統 <a class="header-anchor" href="#擴展文件系統" aria-label="Permalink to “擴展文件系統”">​</a></h5><p>如果你使用了 <code>-r</code> 選項，擴展邏輯卷也將擴展器文件系統。如果你不使用 <code>-r</code> 選項，該操作不行單獨執行。下面的命令在新調整大小的邏輯卷中調整了文件系統大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>resize2fs /dev/MyVG01/Stuff</span></span></code></pre></div><p>你也可以去檢查並校驗調整大小的卷是否正確。你可以使用 <code>df</code>、<code>lvs</code> 和 <code>vgs</code> 命令去做這些工作。</p><h3 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to “提示”">​</a></h3><p>過去幾年來，我學習了怎麼去做讓邏輯卷管理更加容易的一些知識，希望這些提示對你有價值。</p><ul><li>除非你有一個明確的原因去使用其它的文件系統外，推薦使用可擴展的文件系統。除了 EXT2、3、和 4 外，並不是所有的文件系統都支持調整大小。EXT 文件系統不但速度快，而且它很高效。在任何情況下，如果默認的參數不能滿足你的需要，它們（指的是文件系統參數）可以通過一位知識豐富的系統管理員來調優它。</li><li>使用有意義的卷和卷組名字。</li><li>使用 EXT 文件系統標籤</li></ul><p>我知道，像我一樣，大多數的系統管理員都抗拒邏輯卷管理。我希望這篇文章能夠鼓勵你至少去嘗試一個 LVM。如果你能那樣做，我很高興；因為，自從我使用它之後，我的硬盤管理任務變得如此的簡單。</p><h3 id="關於作者" tabindex="-1">關於作者 <a class="header-anchor" href="#關於作者" aria-label="Permalink to “關於作者”">​</a></h3>',75)),s("p",null,[l(i,{href:"https://opensource.com/users/dboth"},{default:t(()=>[...e[0]||(e[0]=[s("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/david-crop.jpg?itok=oePpOpyV",alt:""},null,-1)])]),_:1})]),e[15]||(e[15]=s("p",null,"David Both 是一位 Linux 和開源軟件的倡導者，住在 Raleigh, North Carolina。他在 IT 行業工作了 40 多年，在 IBM 工作了 20 多年。在 IBM 期間，他在 1981 年為最初的 IBM PC 編寫了第一個培訓課程。他曾教授紅帽的 RHCE 課程，並在 MCI Worldcom、Cisco和 North Carolina 工作。他已經使用 Linux 和開源軟件工作了將近 20 年。",-1)),e[16]||(e[16]=s("hr",null,null,-1)),s("p",null,[e[2]||(e[2]=a("via: ",-1)),l(i,{href:"https://opensource.com/business/16/9/linux-users-guide-lvm"},{default:t(()=>[...e[1]||(e[1]=[a("https://opensource.com/business/16/9/linux-users-guide-lvm",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=a("作者：",-1)),l(i,{href:"a"},{default:t(()=>[...e[3]||(e[3]=[a("David Both",-1)])]),_:1}),e[7]||(e[7]=a(" 譯者：",-1)),l(i,{href:"https://github.com/qhwdw"},{default:t(()=>[...e[4]||(e[4]=[a("qhwdw",-1)])]),_:1}),e[8]||(e[8]=a(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=a("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[9]||(e[9]=[a("LCTT",-1)])]),_:1}),e[12]||(e[12]=a(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:t(()=>[...e[10]||(e[10]=[a("Linux中國",-1)])]),_:1}),e[13]||(e[13]=a(" 榮譽推出",-1))])])}const L=n(h,[["render",c]]);export{V as __pageData,L as default};
